CREATE TABLE "${primehrSchema}".rr_award_record(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,evaluation_case_id VARCHAR(36) NOT NULL,nomination_id VARCHAR(36) NOT NULL,cycle_id VARCHAR(36) NOT NULL,category_version_id VARCHAR(36) NOT NULL,award_code VARCHAR(80) NOT NULL,revision_no INTEGER NOT NULL,original_record BOOLEAN NOT NULL,record_key VARCHAR(80) NOT NULL,root_award_id VARCHAR(36) NOT NULL,supersedes_award_id VARCHAR(36),record_type VARCHAR(20) NOT NULL,nominee_type VARCHAR(30) NOT NULL,nominee_display_name VARCHAR(500) NOT NULL,category_title VARCHAR(300) NOT NULL,certificate_title VARCHAR(500),publication_citation VARCHAR(6000),conferred_on DATE,change_reason VARCHAR(4000) NOT NULL,authorized_by VARCHAR(100) NOT NULL,authorized_at TIMESTAMP WITH TIME ZONE NOT NULL,source_fingerprint VARCHAR(64) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_rr_award_case FOREIGN KEY(evaluation_case_id) REFERENCES "${primehrSchema}".rr_evaluation_case(id),CONSTRAINT fk_rr_award_nomination FOREIGN KEY(nomination_id) REFERENCES "${primehrSchema}".rr_nomination(id),CONSTRAINT fk_rr_award_cycle FOREIGN KEY(cycle_id) REFERENCES "${primehrSchema}".rr_award_cycle(id),CONSTRAINT fk_rr_award_category FOREIGN KEY(category_version_id) REFERENCES "${primehrSchema}".rr_award_category_version(id),CONSTRAINT fk_rr_award_root FOREIGN KEY(root_award_id) REFERENCES "${primehrSchema}".rr_award_record(id),CONSTRAINT fk_rr_award_supersedes FOREIGN KEY(supersedes_award_id) REFERENCES "${primehrSchema}".rr_award_record(id),CONSTRAINT uk_rr_award_revision UNIQUE(agency_id,award_code,revision_no),CONSTRAINT uk_rr_award_record_key UNIQUE(agency_id,record_key),CONSTRAINT ck_rr_award_type CHECK(record_type IN('CONFERMENT','CORRECTION','REVOCATION')),CONSTRAINT ck_rr_award_revision CHECK(revision_no>0));
CREATE INDEX ix_rr_award_register ON "${primehrSchema}".rr_award_record(agency_id,conferred_on,record_type);CREATE INDEX ix_rr_award_case ON "${primehrSchema}".rr_award_record(agency_id,evaluation_case_id);
CREATE TABLE "${primehrSchema}".rr_incentive_authorization(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,award_record_id VARCHAR(36) NOT NULL,incentive_type VARCHAR(20) NOT NULL,description VARCHAR(1000) NOT NULL,authorized_amount NUMERIC(19,2),currency_code VARCHAR(3),authorization_reference VARCHAR(200) NOT NULL,authorized_by VARCHAR(100) NOT NULL,authorized_at TIMESTAMP WITH TIME ZONE NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_rr_incentive_award FOREIGN KEY(award_record_id) REFERENCES "${primehrSchema}".rr_award_record(id),CONSTRAINT ck_rr_incentive_type CHECK(incentive_type IN('MONETARY','NON_MONETARY')),CONSTRAINT ck_rr_incentive_amount CHECK((incentive_type='MONETARY' AND authorized_amount>0 AND currency_code IS NOT NULL) OR (incentive_type='NON_MONETARY' AND authorized_amount IS NULL AND currency_code IS NULL)));CREATE INDEX ix_rr_incentive_award ON "${primehrSchema}".rr_incentive_authorization(agency_id,award_record_id);
CREATE TABLE "${primehrSchema}".rr_fulfillment_event(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,authorization_id VARCHAR(36) NOT NULL,status VARCHAR(30) NOT NULL,fulfilled_amount NUMERIC(19,2),details VARCHAR(3000) NOT NULL,evidence_reference VARCHAR(500),evidence_checksum VARCHAR(64),recorded_by VARCHAR(100) NOT NULL,recorded_at TIMESTAMP WITH TIME ZONE NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_rr_fulfillment_authorization FOREIGN KEY(authorization_id) REFERENCES "${primehrSchema}".rr_incentive_authorization(id),CONSTRAINT ck_rr_fulfillment_status CHECK(status IN('PARTIALLY_FULFILLED','FULFILLED','CANCELLED')),CONSTRAINT ck_rr_fulfillment_amount CHECK(fulfilled_amount IS NULL OR fulfilled_amount>0));CREATE INDEX ix_rr_fulfillment_authorization ON "${primehrSchema}".rr_fulfillment_event(agency_id,authorization_id,recorded_at);
CREATE TABLE "${primehrSchema}".rr_hap_endorsement_event(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,award_record_id VARCHAR(36) NOT NULL,status VARCHAR(20) NOT NULL,external_reference VARCHAR(300),details VARCHAR(3000) NOT NULL,recorded_by VARCHAR(100) NOT NULL,recorded_at TIMESTAMP WITH TIME ZONE NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_rr_hap_award FOREIGN KEY(award_record_id) REFERENCES "${primehrSchema}".rr_award_record(id),CONSTRAINT ck_rr_hap_status CHECK(status IN('PREPARED','ENDORSED','SUBMITTED','ACKNOWLEDGED','RETURNED','WITHDRAWN')));CREATE INDEX ix_rr_hap_award ON "${primehrSchema}".rr_hap_endorsement_event(agency_id,award_record_id,recorded_at);
